import { useState } from "react";
import Fill from "../components/Fill";
import { Link } from "react-router-dom";

export default function AddUsers() {
    const [users, setUsers] = useState([]);

    const handlePersonAdd = (user) => {
        setUsers((prevUsers) => [...prevUsers, { ...user, id: Date.now() }]);
    };

    return (
        <div className="text-center">
            <Link to="/users">Go back to users list</Link>
            <Fill onPersonAdd={handlePersonAdd} />

            {users.length > 0 && (
                <div style={{ marginTop: "20px" }}>
                    <h3>Added Users</h3>
                    <table style={{ margin: "0 auto", borderCollapse: "collapse" }}>
                        <thead>
                            <tr>
                                <th style={{ border: "1px solid #ccc", padding: "8px" }}>Name</th>
                                <th style={{ border: "1px solid #ccc", padding: "8px" }}>Email</th>
                                <th style={{ border: "1px solid #ccc", padding: "8px" }}>Phone</th>
                            </tr>
                        </thead>
                        <tbody>
                            {users.map((user) => (
                                <tr key={user.id}>
                                    <td style={{ border: "1px solid #ccc", padding: "8px" }}>{user.name}</td>
                                    <td style={{ border: "1px solid #ccc", padding: "8px" }}>{user.email}</td>
                                    <td style={{ border: "1px solid #ccc", padding: "8px" }}>{user.phone}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
}
